-- Generated by `k2gen generate` from contracts/. Do not edit: change the contract, then `make generate`.
-- Source: contracts/governance/landed-files/bronze.source_files.odcs.yaml
CREATE TABLE IF NOT EXISTS lake.bronze.source_files (
    domain       STRING NOT NULL COMMENT 'The data domain of the source, as contracts/domains.yaml names it.',
    product      STRING NOT NULL COMMENT 'The data product of the source, as its product.yaml names it.',
    url          STRING NOT NULL COMMENT 'The URL the file was fetched from.',
    fetched_at   TIMESTAMP NOT NULL COMMENT 'When the fetch step downloaded the file, UTC, from the metadata of the landed object.',
    sha256       STRING NOT NULL COMMENT 'The sha256 of the bytes of the file, in hex, and the source_file_sha256 every row loaded from it carries.',
    landing_path STRING NOT NULL COMMENT 'Where the file lies, s3://<bucket>/<domain>/<product>/<fetch date>/<sha256>.<ext>.',
    byte_size    BIGINT NOT NULL COMMENT 'The size of the file in bytes.'
)
USING iceberg
TBLPROPERTIES (
    'format-version' = '2',
    'write.format.default' = 'parquet',
    'write.parquet.compression-codec' = 'zstd',
    'write.distribution-mode' = 'hash',
    'write.delete.mode' = 'copy-on-write',
    'write.update.mode' = 'copy-on-write',
    'write.merge.mode' = 'copy-on-write',
    'comment' = 'One row per file a file source landed, append-only, written by the load step of docker/lake/file_source.py before it parses the file, so a file that fails to parse or to audit is recorded too. A file landed again on another day is another row. No upstream is declared: the rows describe the landing zone, which every file source writes, and a list of the URL of every source would say less than the code does.'
);
